export const DISTRICTS = [
  { name: 'Old Town', x0: 0, y0: 0, x1: 960, y1: 960, ground: '#3d4a35' },
  { name: 'Downtown', x0: 960, y0: 0, x1: 1920, y1: 960, ground: '#45424a' },
