  { name: 'South Beach', x0: 1920, y0: 960, x1: 2560, y1: 1920, ground: '#5a4a33' },
];

export function districtAt(x, y) {
  for (const d of DISTRICTS) {
    if (x >= d.x0 && x < d.x1 && y >= d.y0 && y < d.y1) return d.name;
